// Nightly freshness, direct shape (knowledge spec §6 as-built, operator
// decision 2026-09-02): call knowledge-mcp `reingest` with the scoped
// reingest-bot token n8n already holds — zero new secrets. The jobs-mcp
// `knowledge-reingest` task type stays for manual enqueues and becomes the
// scheduler again once jobs-mcp has per-caller tokens.
const day = new Date().toISOString().slice(0, 10);
return [{ json: { rpc: { jsonrpc: '2.0', id: `direct-${day}`, method: 'tools/call', params: { name: 'reingest', arguments: { corpus: 'homelab-notes' } } } } }];

// Fail the execution loudly on anything but a CLEAN sweep (knowledge spec §6:
// index_as_of advances only then). Sustained failure surfaces as
// KnowledgeIndexStale; each failure is visible in n8n execution history.
const res = $input.first().json; // fullResponse: {data|body, headers, statusCode}
const raw = res.data ?? res.body;
const text = typeof raw === 'string' ? raw : JSON.stringify(raw ?? '');
let payload = null;
for (const line of text.split(/\r?\n/)) if (line.startsWith('data:')) payload = line.slice(5).trim();
if (payload === null) payload = text.trim();
let rpc = null;
try { rpc = JSON.parse(payload); } catch {}
if (res.statusCode !== 200 || !rpc) throw new Error(`knowledge-mcp returned ${res.statusCode}${rpc && rpc.code ? ' ' + rpc.code : ''}`);
if (rpc.error) throw new Error(`rpc error: ${String(rpc.error.message ?? '').slice(0, 200)}`);
let tool = null;
try { tool = JSON.parse(rpc.result?.content?.[0]?.text ?? ''); } catch {}
if (!tool) throw new Error('unparseable tool result');
if (rpc.result?.isError) throw new Error(`reingest failed: ${String(tool.code ?? 'E_INTERNAL')} ${String(tool.message ?? '').slice(0, 200)}`);
if (Array.isArray(tool.errors) && tool.errors.length > 0) {
  const named = tool.errors.slice(0, 5).map((e) => `${e.code} ${String(e.uri ?? '').split('/').slice(6).join('/')}`).join('; ');
  throw new Error(`${tool.errors.length} document(s) failed (index_as_of not advanced): ${named}`);
}
return [{ json: { corpus: tool.corpus, source_ref: tool.source_ref, indexed: tool.indexed, unchanged: tool.unchanged, tombstoned: tool.tombstoned } }];
